import sys
s = sys.stdin.read().rstrip('\r\n')
ans = 0
def bt(start):
    global ans
    if start == len(s):
        ans += 1
        return
    for end in range(start + 1, len(s) + 1):
        sub = s[start:end]
        if sub == sub[::-1]:
            bt(end)
if s:
    bt(0)
    print(ans)
else:
    print(0)
